import re

REFERENCE = re.compile(r"#([A-Za-z0-9_]+)((?:\.[A-Za-z0-9_]+)*)#")
ACTION = re.compile(r"\[([A-Za-z0-9_]+):#([A-Za-z0-9_]+)#\]")


def flatten(text, grammar, choose, modifiers=None, depth=0):
    if depth > 50:
        raise RecursionError("expansion did not terminate")
    modifiers = modifiers or {}
    saved = {}

    def run_action(match):
        key, symbol = match.group(1), match.group(2)
        saved[key] = flatten(f"#{symbol}#", grammar, choose, modifiers, depth + 1)
        return ""

    text = ACTION.sub(run_action, text)

    def run_reference(match):
        name, chain = match.group(1), match.group(2)
        if name in saved:
            value = saved[name]
        elif name in grammar:
            rules = grammar[name]
            if not rules:
                raise ValueError(f"symbol {name!r} has no rules")
            value = flatten(choose(rules), grammar, choose, modifiers, depth + 1)
        else:
            return f"(({name}))"
        for step in [s for s in chain.split(".") if s]:
            if step not in modifiers:
                value = f"{value}(({step}))"
            else:
                value = modifiers[step](value)
        return value

    return REFERENCE.sub(run_reference, text)
